// Wrap deck.html in a Roam render function (iframe with srcDoc), and check the result.
// Usage: node wrap-for-roam.mjs deck.html accounts-deck-roam-render.js
import fs from "node:fs";

const [src, out] = process.argv.slice(2);
const html = fs.readFileSync(src, "utf8");
const wrapper = `const ACCOUNTS_DECK_HTML = "__HTML_SOURCE__";

function accountsTeamDeck(props) {
  const React = window.React;
  if (!React) return null;

  return React.createElement("iframe", {
    title: "Personal accounts: team presentation",
    srcDoc: ACCOUNTS_DECK_HTML,
    sandbox: "allow-scripts",
    loading: "eager",
    style: {
      width: "100%",
      height: "calc(100vh - 140px)",
      minHeight: "720px",
      display: "block",
      border: "1px solid #d8d2c5",
      borderRadius: "10px",
      background: "#f4f0e6",
    },
  });
}
`;
const LS = String.fromCharCode(0x2028);
const PS = String.fromCharCode(0x2029);
const htmlLiteral = JSON.stringify(html).split(LS).join("\\u2028").split(PS).join("\\u2029");
const renderer = wrapper.replace('"__HTML_SOURCE__"', () => htmlLiteral);
fs.writeFileSync(out, renderer);

const evaluated = new Function(renderer + "\nreturn ACCOUNTS_DECK_HTML;")();
if (evaluated !== html) {
  console.error("MISMATCH: srcDoc differs from the HTML");
  process.exit(1);
}
console.log("srcDoc matches the HTML exactly");

