    location /.well-known {
        #This is for domain verification
        alias /var/www/html/.well-known;
        add_header Access-Control-Allow-Origin * always;
    }

    return 301 https://www.conversence.com$request_uri;
}

server {
    listen   443 ssl;
    listen   [::]:443 ssl;
    http2 on;

    ssl_certificate     /etc/letsencrypt/live/conversence.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/conversence.com/privkey.pem;
    include /etc/letsencrypt/options-ssl-nginx.conf;

    # This corresponds to an intermediate configuration on https://mozilla.github.io/server-side-tls/ssl-config-generator/
    ssl_dhparam /etc/nginx/dhparams.pem;
    add_header Strict-Transport-Security max-age=15768000;
    ssl_stapling on;
    ssl_stapling_verify on;
    ## verify chain of trust of OCSP response using Root CA and Intermediate certs
    ssl_trusted_certificate /etc/letsencrypt/live/conversence.com/chain.pem;

    # resolver <IP DNS resolver>;

    add_header x-xss-protection "1; mode=block" always;
    add_header x-frame-options "SAMEORIGIN" always;
    add_header X-Content-Type-Options "nosniff" always;

    server_tokens off;
    # Optional for extra security
    add_header Content-Security-Policy "default-src 'self' https://www.googletagmanager.com https://www.google-analytics.com; script-src 'self' 'unsafe-inline' 'unsafe-eval' data: https://www.googletagmanager.com https://www.google-analytics.com https://ssl.google-analytics.com https://unpkg.com/; frame-src 'self' www.youtube.com ; connect-src 'self' https://www.google-analytics.com; style-src 'self' 'unsafe-inline' http://fonts.googleapis.com ; font-src 'self' data: fonts.gstatic.com; img-src 'self' data: https://www.google-analytics.com https://ssl.google-analytics.com https://www.googletagmanager.com";

    # This is the server name, assuming you're running multiple servers
    server_name www.conversence.com;

    location /.well-known {
        #This is for domain verification
        alias /var/www/html/.well-known;
	add_header Access-Control-Allow-Origin * always;
    }

    location /plantuml {
       rewrite /plantuml/(.*) /$1 break;
       proxy_set_header Host $host;
       proxy_set_header X-Real-IP $remote_addr;
       proxy_set_header X-Forwarded-For $remote_addr;
       proxy_set_header X-Forwarded-Proto $scheme;
       proxy_set_header X-Frame-Options SAMEORIGIN;
       proxy_pass http://127.0.0.1:5111/plantuml;
    }

    location /plantuml_deflate {
        include uwsgi_params;
        uwsgi_pass unix:///home/maparent/plantuml_deflate/run/uwsgi.sock;
    }

    root /var/www/conversence.com/html;

    location /dg/presentations/ {
      add_header Content-Security-Policy "frame-ancestors 'self' https://roamresearch.com" always;
    }

    #auth_basic "Work in Progress";
    #auth_basic_user_file /etc/nginx/.htpasswd;
}
